const MTL_TEXT = `# Color definition for Tinkercad Obj File 2015

newmtl color_2829873
Ka 0 0 0 
Kd 0.03 0.03 0.035
d 1
illum 0.0

newmtl color_16448250
Ka 0 0 0 
Kd 0.38 0.38 0.38
d 1
illum 0.0

newmtl color_16777215
Ka 0 0 0 
Kd 0.4 0.4 0.4
d 1
illum 0.0

`;

// -- carrega o modelo 3D uma unica vez e clona-o para cada visualizador --
let BASE_OBJECT = null;
if(typeof THREE !== 'undefined'){
 try{
  const mtlLoader = new THREE.MTLLoader();
  const materials = mtlLoader.parse(MTL_TEXT, '');
  materials.preload();
  const objLoader = new THREE.OBJLoader();
  objLoader.setMaterials(materials);
  BASE_OBJECT = objLoader.parse(OBJ_TEXT);
  BASE_OBJECT.traverse(child=>{
   if(child.isMesh && child.geometry && !child.geometry.attributes.normal){
    child.geometry.computeVertexNormals();
   }
  });
  // aplica primeiro a correcao de eixo (Tinkercad é Z-up) para a orientacao final ficar correta
  BASE_OBJECT.rotation.x = -Math.PI/2;
  BASE_OBJECT.updateMatrixWorld(true);
  let box = new THREE.Box3().setFromObject(BASE_OBJECT);
  let size = box.getSize(new THREE.Vector3());
  const maxDim = Math.max(size.x, size.y, size.z) || 1;
  BASE_OBJECT.scale.setScalar(130/maxDim);
  // recalcula a caixa envolvente ja com a orientacao e escala finais para achar o verdadeiro centro geometrico
  BASE_OBJECT.updateMatrixWorld(true);
  box = new THREE.Box3().setFromObject(BASE_OBJECT);
  const center = box.getCenter(new THREE.Vector3());
  BASE_OBJECT.position.sub(center);
 }catch(err){
  console.error('Falha ao ler o modelo 3D', err);
 }
}

function create3DViewer(opts){
 const container = document.getElementById(opts.containerId);
 if(!container) return;
 const hint = document.getElementById(opts.hintId);
 const loading = document.getElementById(opts.loadingId);

 function hideHint(){ if(hint && !hint.classList.contains('hide')) hint.classList.add('hide'); }

 if(typeof THREE === 'undefined'){
  if(loading) loading.textContent = 'Não foi possível carregar o visualizador 3D.';
  return;
 }

 const width = container.clientWidth || 400, height = container.clientHeight || 400;
 const scene = new THREE.Scene();
 const camera = new THREE.PerspectiveCamera(32, width/height, 1, 5000);
 camera.position.set(0, 0, opts.dist || 260);
 camera.lookAt(0, 0, 0);

 const renderer = new THREE.WebGLRenderer({antialias:true, alpha:true});
 renderer.setSize(width, height);
 renderer.setPixelRatio(Math.min(window.devicePixelRatio||1, 2));
 container.appendChild(renderer.domElement);

 scene.add(new THREE.AmbientLight(0xffffff, 0.7));
 const key = new THREE.DirectionalLight(0xffffff, 0.9); key.position.set(150,220,180); scene.add(key);
 const fill = new THREE.DirectionalLight(0xffffff, 0.35); fill.position.set(-180,-60,-120); scene.add(fill);
 const rim = new THREE.DirectionalLight(0xffffff, 0.4); rim.position.set(0,120,-220); scene.add(rim);

 const group = new THREE.Group();
 if(opts.yOffset) group.position.y = opts.yOffset;
 scene.add(group);

 if(BASE_OBJECT){
  const obj = opts.cloneObject ? BASE_OBJECT.clone(true) : BASE_OBJECT;
  group.add(obj);
  if(loading) loading.style.display = 'none';
 }else if(loading){
  loading.textContent = 'Não foi possível ler o modelo 3D.';
 }

 let rotY = opts.initialRotY !== undefined ? opts.initialRotY : Math.PI/2;
 let rotX = opts.initialRotX !== undefined ? opts.initialRotX : 0.15;
 function applyRot(){ group.rotation.y = rotY; group.rotation.x = rotX; }
 applyRot();

 let dragging=false, lastX=0, lastY=0;
 function down(x,y){ dragging=true; lastX=x; lastY=y; container.classList.add('dragging'); hideHint(); }
 function move(x,y){
  if(!dragging) return;
  const dx=x-lastX, dy=y-lastY;
  rotY += dx*0.008;
  rotX += dy*0.008;
  applyRot();
  lastX=x; lastY=y;
 }
 function up(){ dragging=false; container.classList.remove('dragging'); }
 renderer.domElement.addEventListener('mousedown', e=>down(e.clientX,e.clientY));
 window.addEventListener('mousemove', e=>move(e.clientX,e.clientY));
 window.addEventListener('mouseup', up);
 renderer.domElement.addEventListener('touchstart', e=>{ const t=e.touches[0]; down(t.clientX,t.clientY); }, {passive:true});
 window.addEventListener('touchmove', e=>{ const t=e.touches[0]; move(t.clientX,t.clientY); }, {passive:true});
 window.addEventListener('touchend', up);

 function animate(){
  requestAnimationFrame(animate);
  rotY += 0.0025;
  applyRot();
  renderer.render(scene, camera);
 }
 animate();

 window.addEventListener('resize', ()=>{
  const w = container.clientWidth, h = container.clientHeight;
  if(!w || !h) return;
  camera.aspect = w/h; camera.updateProjectionMatrix();
  renderer.setSize(w,h);
 });
}

create3DViewer({containerId:'hero-viewer3d', hintId:'hero-hint', loadingId:'hero-loading3d', dist:380, cloneObject:true, initialRotY:Math.PI/2, initialRotX:0.12});
create3DViewer({containerId:'viewer3d', hintId:'config-hint', loadingId:'loading3d', dist:320, cloneObject:false, initialRotY:Math.PI/2, initialRotX:0.18, yOffset:-18});

// -- personalizacao: acabamento + buzzer + preco dinamico --
const BASE_PRICE = 100;
let finishPrice = 0, finishName = 'Normal';
let buzzerPrice = 0, buzzerName = 'Sem Buzzer';

function updateSummary(){
 document.getElementById('sum-finish').textContent = finishName + (finishPrice ? ' (+€' + finishPrice + ')' : '');
 document.getElementById('sum-buzzer').textContent = buzzerName + (buzzerPrice ? ' (+€' + buzzerPrice + ')' : '');
 const total = BASE_PRICE + finishPrice + buzzerPrice;
 const label = '≈ €' + total;
 document.getElementById('sum-price').textContent = label;
 document.getElementById('final-price').textContent = label;
}

function wireSingleSelect(groupId, onPick){
 const group = document.getElementById(groupId);
 group.querySelectorAll('.swatch').forEach(sw=>{
  sw.addEventListener('click', ()=>{
   group.querySelectorAll('.swatch').forEach(s=>s.classList.remove('active'));
   sw.classList.add('active');
   onPick(sw.dataset.value, parseInt(sw.dataset.price,10)||0);
  });
 });
}

wireSingleSelect('finish-swatches', (name,price)=>{ finishName=name; finishPrice=price; updateSummary(); });
wireSingleSelect('buzzer-swatches', (name,price)=>{ buzzerName=name; buzzerPrice=price; updateSummary(); });

updateSummary();

// -- checkout: overlay dentro da propria pagina (mais fiavel que aba nova aqui) --
const checkoutOverlay = document.getElementById('checkoutOverlay');
let coAccountReady = false, coDiscountApplied = false;

document.getElementById('checkoutClose').addEventListener('click', ()=>{
 checkoutOverlay.classList.remove('open');
 document.body.style.overflow = '';
});

document.getElementById('buy-btn').addEventListener('click', ()=>{
 document.getElementById('co-sum-finish').textContent = finishName + (finishPrice ? ' (+€'+finishPrice+')' : '');
 document.getElementById('co-sum-buzzer').textContent = buzzerName + (buzzerPrice ? ' (+€'+buzzerPrice+')' : '');
 const subtotal = BASE_PRICE + finishPrice + buzzerPrice;
 document.getElementById('co-subtotal').textContent = '€' + subtotal;
 document.getElementById('co-total').textContent = '€' + subtotal;
 checkoutOverlay.dataset.subtotal = subtotal;
 checkoutOverlay.classList.add('open');
 document.body.style.overflow = 'hidden';
});

document.getElementById('co-account-btn').addEventListener('click', function(){
 const name = document.getElementById('co-name').value.trim();
 const email = document.getElementById('co-email').value.trim();
 const pass = document.getElementById('co-pass').value;
 const msg = document.getElementById('co-account-msg');
 if(!name || !email || !pass){ msg.style.display = 'block'; return; }
 msg.style.display = 'none';
 coAccountReady = true;
 document.getElementById('co-address-step').classList.remove('co-locked');
 document.getElementById('co-payment-step').classList.remove('co-locked');
 document.getElementById('co-summary-step').classList.remove('co-locked');
 this.textContent = 'Conta criada ✓';
 this.disabled = true;
});

document.querySelectorAll('#checkoutOverlay .pay-option').forEach(opt=>{
 opt.addEventListener('click', ()=>{
  document.querySelectorAll('#checkoutOverlay .pay-option').forEach(o=>o.classList.remove('selected'));
  opt.classList.add('selected');
  opt.querySelector('input').checked = true;
 });
});

function coUpdateTotals(){
 const subtotal = parseFloat(checkoutOverlay.dataset.subtotal || '100');
 const discount = coDiscountApplied ? Math.round(subtotal*0.05*100)/100 : 0;
 const total = Math.round((subtotal - discount)*100)/100;
 document.getElementById('co-discount').textContent = '-€' + discount.toFixed(2);
 document.getElementById('co-total').textContent = '€' + total.toFixed(2);
 document.getElementById('co-discount-row').style.display = coDiscountApplied ? 'flex' : 'none';
}

document.getElementById('co-apply-code').addEventListener('click', function(){
 const code = document.getElementById('co-code').value.trim().toUpperCase();
 const msg = document.getElementById('co-code-msg');
 if(coDiscountApplied){ msg.className = 'co-msg ok'; msg.textContent = 'Código já aplicado.'; return; }
 if(code === 'DDUG1'){
  coDiscountApplied = true;
  msg.className = 'co-msg ok';
  msg.textContent = 'Código aplicado: -5%';
  coUpdateTotals();
 } else {
  msg.className = 'co-msg err';
  msg.textContent = 'Código inválido.';
 }
});

document.getElementById('co-finish-btn').addEventListener('click', function(){
 if(!coAccountReady){ alert('Cria a tua conta primeiro.'); return; }
 document.querySelectorAll('#checkoutOverlay .co-step').forEach(s=> s.style.display = 'none');
 document.querySelector('#checkoutOverlay .fine').style.display = 'none';
 document.getElementById('co-confirm').style.display = 'block';
});
